package com.fitmind.service;
import com.fitmind.dto.*; import com.fitmind.entity.UserProfile; import com.fitmind.exception.BusinessException; import com.fitmind.mapper.UserProfileMapper; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class ProfileService { public static final long USER_ID=1L; private final UserProfileMapper mapper; public UserProfile get(){UserProfile p=mapper.selectById(USER_ID);if(p==null)throw BusinessException.notFound("用户资料不存在");return p;} public UserProfile update(ProfileUpdateRequest r){UserProfile p=get();p.setNickname(r.getNickname());p.setStartWeightKg(r.getStartWeightKg());p.setTargetWeightKg(r.getTargetWeightKg());mapper.updateById(p);return get();} public UserProfile updateUnit(WeightUnitRequest r){UserProfile p=get();p.setPreferredWeightUnit(r.getPreferredWeightUnit());mapper.updateById(p);return get();} }
